mapper.select:
SELECT faqNumber, faqCategory, faqQuestion, faqAnswer FROM ( SELECT NOTICE_NUMBER AS faqNumber, 'FAQ' AS faqCategory, NOTICE_TITLE AS faqQuestion, NOTICE_CONTENT AS faqAnswer, ROW_NUMBER() OVER (ORDER BY NOTICE_NUMBER DESC) AS rn FROM FAQ WHERE 1 = 1
AND ( NOTICE_TITLE LIKE '%' || #{keyword} || '%' OR DBMS_LOB.INSTR(NOTICE_CONTENT, #{keyword}) > 0 )
) WHERE rn BETWEEN #{startRow} AND #{endRow} ORDER BY rn
